import type {
  QuartzComponent,
  QuartzComponentConstructor,
  QuartzComponentProps,
} from "@quartz-community/types"
import { classNames } from "@quartz-community/utils"
import style from "./styles/banner.scss"

// site-absolute path used when a page has no `banner` frontmatter
export const defaultBanner = "/static/library.webp"

// widths generated by BannerImages; the banner column is at most 750px wide
export const bannerWidths = [800, 1600]

/** Site-absolute banner URL for a page, or null when the page has `banner: none`. */
export function bannerUrl(frontmatter: { banner?: string } | undefined): string | null {
  const banner = frontmatter?.banner ?? defaultBanner
  if (!banner || banner === "none") return null
  return banner.startsWith("/") || banner.startsWith("http") ? banner : `/${banner}`
}

/** Local raster banners get resized copies (`name-800.webp`, …); remote and SVG ones don't. */
export function bannerVariant(url: string, width: number): string | null {
  if (url.startsWith("http") || !/\.(webp|png|jpe?g)$/i.test(url)) return null
  return url.replace(/\.[^.]+$/, `-${width}.webp`)
}

export default (() => {
  const Banner: QuartzComponent = ({ fileData, displayClass }: QuartzComponentProps) => {
    const url = bannerUrl(fileData.frontmatter as { banner?: string } | undefined)
    if (!url) {
      return null
    }
    const srcset = bannerWidths
      .map((w) => [bannerVariant(url, w), w] as const)
      .filter(([variant]) => variant)
      .map(([variant, w]) => `${variant} ${w}w`)
      .join(", ")
    return (
      <img
        class={classNames(displayClass, "page-banner")}
        src={url}
        srcset={srcset || undefined}
        sizes={srcset ? "(max-width: 800px) calc(100vw - 2rem), 750px" : undefined}
        decoding="async"
        alt=""
      />
    )
  }

  Banner.css = style

  return Banner
}) satisfies QuartzComponentConstructor
